import { readFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"

/**
 * Test-only loader for the gateway-produced profile signature vectors.
 *
 * `profile-signature/vectors.json` is a byte copy of the file generated by
 * the gateway (`lib/http_tools/tests/profile_signature_contract.rs`).
 */

export interface ContractVector {
  name: string
  description: string
  profileHeader: string
  signature: string
  trustedKeyVersions: string[]
  nowSeconds: number
  toleranceSeconds: number
  expectedAudience: string | null
  expected: string
}

export interface SignatureContract {
  publicKeys: Record<string, string>
  expectedValidProfile: { accId: string; isStaff: boolean }
  vectors: ContractVector[]
}

const here = dirname(fileURLToPath(import.meta.url))

export const CONTRACT_FILE = join(here, "profile-signature", "vectors.json")

export const GATEWAY_CONTRACT_FILE = join(
  here,
  "..",
  "..",
  "..",
  "mycelium-api-gateway",
  "lib",
  "http_tools",
  "test",
  "mock",
  "profile-signature",
  "vectors.json"
)

export const CONTRACT = JSON.parse(
  readFileSync(CONTRACT_FILE, "utf8")
) as SignatureContract

export function vectorNamed(name: string): ContractVector {
  const vector = CONTRACT.vectors.find((candidate) => candidate.name === name)
  if (vector === undefined) throw new Error(`unknown vector ${name}`)
  return vector
}

export function environmentFor(
  versions: string[],
  extra: Record<string, string> = {}
): Record<string, string> {
  const env: Record<string, string> = { ...extra }
  for (const version of versions) {
    const pem = CONTRACT.publicKeys[version]
    if (pem === undefined) throw new Error(`unknown key ${version}`)
    env[`MYC_PROFILE_PUBLIC_KEY_${version}`] = pem
  }
  return env
}
